{
  "name": "Agilent BioTek 多功能微孔板读板仪",
  "name_en": "Agilent BioTek multimode microplate reader",
  "manufacturer": "Agilent BioTek",
  "description": "这是一种台式微孔板读板仪，用于对微孔板中的样品进行吸光度、荧光和发光检测。设备通常带有载板抽屉、温度控制和振荡功能，适用于生化分析、细胞实验和高通量筛选等实验室检测工作。",
  "description_en": "A benchtop multimode microplate reader used to measure absorbance, fluorescence, and luminescence from samples in microplates. It typically includes a plate tray, temperature control, and shaking, and is used for biochemical assays, cell-based experiments, and high-throughput screening.",
  "tag_hints": [
    "microplate reader",
    "multimode plate reading",
    "absorbance measurement",
    "fluorescence assays",
    "luminescence assays",
    "temperature control",
    "plate shaking"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭微孔板载板抽屉。",
      "description_en": "Close the microplate tray."
    },
    {
      "action_name": "auto-home",
      "description": "使设备运动机构回零。",
      "description_en": "Home the device motion system."
    },
    {
      "action_name": "auto-open",
      "description": "打开微孔板载板抽屉。",
      "description_en": "Open the microplate tray."
    },
    {
      "action_name": "auto-read_absorbance",
      "description": "测量指定孔位的吸光度。",
      "description_en": "Measure absorbance in the specified wells."
    },
    {
      "action_name": "auto-read_fluorescence",
      "description": "测量指定孔位的荧光信号。",
      "description_en": "Measure fluorescence in the specified wells."
    },
    {
      "action_name": "auto-read_luminescence",
      "description": "测量指定孔位的发光信号。",
      "description_en": "Measure luminescence in the specified wells."
    },
    {
      "action_name": "auto-send_command",
      "description": "向仪器发送原始控制命令。",
      "description_en": "Send a raw control command to the instrument."
    },
    {
      "action_name": "auto-set_plate",
      "description": "定义当前微孔板的几何参数。",
      "description_en": "Define the geometry of the current microplate."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置温控温度。",
      "description_en": "Set the temperature control setpoint."
    },
    {
      "action_name": "auto-setup",
      "description": "初始化读板仪并建立通信。",
      "description_en": "Initialize the plate reader and establish communication."
    },
    {
      "action_name": "auto-shake",
      "description": "启动微孔板振荡。",
      "description_en": "Start shaking the microplate."
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备当前操作。",
      "description_en": "Stop the current device operation."
    },
    {
      "action_name": "auto-stop_heating_or_cooling",
      "description": "停止加热或制冷。",
      "description_en": "Stop heating or cooling."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止微孔板振荡。",
      "description_en": "Stop shaking the microplate."
    },
    {
      "action_name": "auto-version",
      "description": "获取设备版本信息。",
      "description_en": "Get the device version information."
    },
    {
      "action_name": "auto-abs_wavelength_range",
      "description": "获取吸光度测量波长范围。",
      "description_en": "Get the absorbance wavelength range."
    },
    {
      "action_name": "auto-focal_height_range",
      "description": "获取焦距高度范围。",
      "description_en": "Get the focal height range."
    },
    {
      "action_name": "auto-excitation_range",
      "description": "获取激发波长范围。",
      "description_en": "Get the excitation wavelength range."
    },
    {
      "action_name": "auto-emission_range",
      "description": "获取发射波长范围。",
      "description_en": "Get the emission wavelength range."
    },
    {
      "action_name": "auto-supports_heating",
      "description": "获取是否支持加热。",
      "description_en": "Get whether heating is supported."
    },
    {
      "action_name": "auto-supports_cooling",
      "description": "获取是否支持制冷。",
      "description_en": "Get whether cooling is supported."
    },
    {
      "action_name": "auto-temperature_range",
      "description": "获取温控范围。",
      "description_en": "Get the temperature control range."
    },
    {
      "action_name": "auto-get_serial_number",
      "description": "获取序列号。",
      "description_en": "Get the serial number."
    },
    {
      "action_name": "auto-get_firmware_version",
      "description": "获取固件版本。",
      "description_en": "Get the firmware version."
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    }
  ]
}

